const renameDataset = `-- name: RenameDataset :one
UPDATE datasets d
SET name = $3,
    updated_at = now()
FROM workspace_members m
WHERE d.id = $1
  AND m.workspace_id = d.workspace_id
  AND m.user_id = $2
  AND d.deleted_at IS NULL
RETURNING d.id, d.workspace_id, d.name, d.description, d.current_version_no, d.created_by, d.created_at, d.updated_at, d.deleted_at, d.purge_after
`

type RenameDatasetParams struct {
	ID     pgtype.UUID
	UserID pgtype.UUID
	Name   string
}

// Membership is checked in-query so a non-member gets the same "not found".
func (q *Queries) RenameDataset(ctx context.Context, arg RenameDatasetParams) (Dataset, error) {
	row := q.db.QueryRow(ctx, renameDataset, arg.ID, arg.UserID, arg.Name)
	var i Dataset
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.CurrentVersionNo,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.PurgeAfter,
	)
	return i, err
}

const softDeleteDataset = `-- name: SoftDeleteDataset :one
UPDATE datasets d
SET deleted_at = now(),
    purge_after = now() + make_interval(days => $3),
    updated_at = now()
FROM workspace_members m
WHERE d.id = $1
  AND m.workspace_id = d.workspace_id
  AND m.user_id = $2
  AND d.deleted_at IS NULL
RETURNING d.id, d.workspace_id, d.name, d.description, d.current_version_no, d.created_by, d.created_at, d.updated_at, d.deleted_at, d.purge_after
`

type SoftDeleteDatasetParams struct {
	ID     pgtype.UUID
	UserID pgtype.UUID
	Days   int32
}

// Soft delete keeps the rows for the grace period; the purge janitor removes
// the files and cascades the rows once purge_after passes.
func (q *Queries) SoftDeleteDataset(ctx context.Context, arg SoftDeleteDatasetParams) (Dataset, error) {
	row := q.db.QueryRow(ctx, softDeleteDataset, arg.ID, arg.UserID, arg.Days)
	var i Dataset
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.CurrentVersionNo,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.PurgeAfter,
	)
	return i, err
}

